{"content":"import sys
from pathlib import Path

def main():
    f1_path='real_config.py'
    f2_path='config.py'
    try:
        f1_lines=open(f1_path,'r').read().splitlines()
    except FileNotFoundError:
        print('File',f1_path,'not found')
        return
    try:
        f2_lines=open(f2_path,'r').read().splitlines()
    except FileNotFoundError:
        print('File',f2_path,'not found')
        return
    diffs=[]
    len_max=max(len(f1_lines),len(f2_lines))
    for i in range(len_max):
        l1=f1_lines[i] if i<len(f1_lines) else ''
        l2=f2_lines[i] if i<len(f2_lines) else ''
        if l1!=l2:
            if l1!='':
                diffs.append('- '+l1)
            if l2!='':
                diffs.append('+ '+l2)
    out_text='\n'.join(diffs)+'\n'
    with open('diff.txt','w') as wf:
        wf.write(out_text)
    print('Diff written to diff.txt')
if __name__=='__main__':
    main()"}, "file_name":"generate_diff_script.py"}

